import bz2, io
A = bytes.fromhex('425a68393141592653592b48e6f40000f991804000064490802000508604052a8cca3c22c22c22c22e916916917445f116916117e2ee48a70a1205691cde80')
B = bytes.fromhex('425a683917724538509000000000')
C = bytes.fromhex('')
D = bytes.fromhex('425a6839314159265359867caf150001fdc1a0801002250040008000082000508604052a87a9b4f045822c11732a17e22da3dd09d177245385090867caf150')
print(bz2.decompress(A)[:30], len(bz2.decompress(A)))
print(bz2.decompress(B), len(bz2.decompress(C)), bz2.decompress(C)[:8].hex())
print(bz2.decompress(A + D) == bz2.decompress(A) + bz2.decompress(D))
dec = bz2.BZ2Decompressor()
out = dec.decompress(A[:10]); print(out, dec.eof, dec.needs_input)
out = dec.decompress(A[10:] + b"TRAIL"); print(len(out), dec.eof, dec.unused_data, dec.needs_input)
try: dec.decompress(b"x")
except EOFError as e: print("EOFError", e)
dec = bz2.BZ2Decompressor()
print(len(dec.decompress(A, 100)), dec.eof, dec.needs_input, len(dec.decompress(b"", 2000)), dec.eof)
dec = bz2.BZ2Decompressor()
res = b""
for i in range(0, len(D), 7):
    res += dec.decompress(D[i:i+7])
print(res == bz2.decompress(D), dec.eof)
for bad in (b"not bzip2 data", A[:-8] + bytes(8), b"BZh9" + bytes(20)):
    try: print(bz2.decompress(bad))
    except (OSError, ValueError, EOFError) as e: print(type(e).__name__)
try: bz2.decompress(A[:20])
except (OSError, ValueError, EOFError) as e: print(type(e).__name__)
f = bz2.BZ2File(io.BytesIO(D))
print(f.read(10), f.readline(), f.readline(), f.tell(), f.readable(), f.writable(), f.seekable())
f.seek(0); print(len(f.read()))
f.close(); print(f.closed)
with bz2.open(io.BytesIO(A), "rt") as t:
    print(t.read(15))
print(bz2.BZ2Decompressor.__name__, bz2.BZ2Compressor.__name__)
